import { siteConfig } from '../config/site';
import { useState } from 'react';

const footerSections = [
  { key: 'shop', title: 'Shop and Learn', links: siteConfig.footerLinks.shop },
  { key: 'wallet', title: 'Orchard Wallet', links: siteConfig.footerLinks.wallet },
  { key: 'account', title: 'Account', links: siteConfig.footerLinks.account },
  { key: 'entertainment', title: 'Entertainment', links: siteConfig.footerLinks.entertainment },
  { key: 'store', title: 'Orchard Store', links: siteConfig.footerLinks.store },
  { key: 'business', title: 'For Business', links: siteConfig.footerLinks.business },
  { key: 'education', title: 'For Education', links: siteConfig.footerLinks.education },
];

export function Footer() {
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({});

  const toggleSection = (key: string) => {
    setOpenSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <footer className="bg-gray-100 mt-16">
      <div className="max-w-6xl mx-auto px-4 py-12">
        {/* Desktop Footer */}
        <div className="hidden md:grid grid-cols-5 gap-8">
          {footerSections.map(section => (
            <div key={section.key}>
              <h3 className="font-semibold text-sm mb-3 text-gray-900">{section.title}</h3>
              <ul className="space-y-2">
                {section.links.map(link => (
                  <li key={link}>
                    <a href="#" className="text-sm text-gray-500 hover:text-gray-900 transition-colors">
                      {link}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        {/* Mobile Footer Accordion */}
        <div className="md:hidden space-y-2">
          {footerSections.map(section => (
            <div key={section.key} className="border-b border-gray-200">
              <button
                onClick={() => toggleSection(section.key)}
                className="w-full flex items-center justify-between py-3 text-sm font-semibold text-gray-900"
              >
                {section.title}
                <svg
                  className={`w-4 h-4 transition-transform ${openSections[section.key] ? 'rotate-180' : ''}`}
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                </svg>
              </button>
              <div className={`footer-accordion-content ${openSections[section.key] ? 'open' : ''}`}>
                <ul className="pb-3 space-y-2">
                  {section.links.map(link => (
                    <li key={link}>
                      <a href="#" className="text-sm text-gray-500 hover:text-gray-900 transition-colors">
                        {link}
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-12 pt-6 border-t border-gray-200">
          <p className="text-xs text-gray-500">
            More ways to shop: <a href="#" className="text-blue-600 hover:underline">Find a retailer</a> near you. Or call 1-800-MY-ORCHARD.
          </p>
          <p className="text-xs text-gray-400 mt-2">
            Copyright © 2026 Orchard Inc. All rights reserved.
          </p>
        </div>
      </div>
    </footer>
  );
}

