import { useState } from 'react';

const footerSections = [
  { key: 'shop', title: 'Shop and Learn', links: siteConfig.footerLinks.shop },
  { key: 'wallet', title: 'Orchard Wallet', links: siteConfig.footerLinks.wallet },
  { key: 'account', title: 'Account', links: siteConfig.footerLinks.account },
  { key: 'entertainment', title: 'Entertainment', links: siteConfig.footerLinks.entertainment },
  { key: 'store', title: 'Orchard Store', links: siteConfig.footerLinks.store },
  { key: 'business', title: 'For Business', links: siteConfig.footerLinks.business },
  { key: 'education', title: 'For Education', links: siteConfig.footerLinks.education },
];

export function Footer() {
  const [openSections, setOpenSections] = useState<Record<string, boolean>>({});

  const toggleSection = (key: string) => {
    setOpenSections(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <footer className="bg-gray-100 mt-16">
