import { useRef, useState, useEffect, ReactNode } from 'react';

interface CarouselProps {
  children: ReactNode;
  title?: string;
  subtitle?: string;
  showArrows?: boolean;
}

export function Carousel({ children, title, subtitle, showArrows = true }: CarouselProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [canScrollPrev, setCanScrollPrev] = useState(false);
  const [canScrollNext, setCanScrollNext] = useState(true);

  const updateScrollButtons = () => {
    if (!trackRef.current) return;
    const { scrollLeft, scrollWidth, clientWidth } = trackRef.current;
    setCanScrollPrev(scrollLeft > 0);
    setCanScrollNext(scrollLeft < scrollWidth - clientWidth - 10);
  };

  useEffect(() => {
    const track = trackRef.current;
    if (track) {
      track.addEventListener('scroll', updateScrollButtons);
      updateScrollButtons();
      return () => track.removeEventListener('scroll', updateScrollButtons);
    }
  }, []);

  const scroll = (direction: 'prev' | 'next') => {
    if (!trackRef.current) return;
    const scrollAmount = 300;
    trackRef.current.scrollBy({
      left: direction === 'next' ? scrollAmount : -scrollAmount,
      behavior: 'smooth',
    });
  };

  return (
    <div className="carousel-container">
      {(title || subtitle) && (
        <div className="mb-6">
          {title && <h2 className="text-3xl font-semibold text-gray-900">{title}</h2>}
          {subtitle && <p className="mt-1 text-gray-500">{subtitle}</p>}
        </div>
      )}
      <div className="relative">
        {showArrows && (
          <>
            <button
              onClick={() => scroll('prev')}
              className={`carousel-btn prev ${!canScrollPrev ? 'opacity-30 pointer-events-none' : ''}`}
              aria-label="Previous"
            >
              <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
              </svg>
            </button>
            <button
              onClick={() => scroll('next')}
              className={`carousel-btn next ${!canScrollNext ? 'opacity-30 pointer-events-none' : ''}`}
              aria-label="Next"
            >
              <svg fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
              </svg>
            </button>
          </>
        )}
        <div ref={trackRef} className="carousel-track">
          {children}
        </div>
      </div>
    </div>
  );
}

