  price: string;
  monthly?: string;
  badge?: string;
  compact?: boolean;
}

export function ProductCard({ name, tagline, price, monthly, badge, compact }: ProductCardProps) {
  return (
    <div className={`product-card ${compact ? 'py-4' : ''}`}>
      {badge && <span className="badge mb-3">{badge}</span>}
      <div className="bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl w-full h-32 mb-4 flex items-center justify-center">
        <span className="text-4xl opacity-50">📦</span>
      </div>
      <h3 className="font-semibold text-lg text-gray-900">{name}</h3>
      <p className="text-sm text-gray-500 mt-1">{tagline}</p>
      <div className="mt-3">
        <p className="font-medium text-gray-900">{price}</p>
        {monthly && <p className="text-xs text-gray-500 mt-0.5">{monthly}</p>}
      </div>
      <div className="mt-4 flex gap-2">
        <a href="#" className="btn-primary text-sm py-2 px-4">Buy</a>
        <a href="#" className="btn-secondary text-sm py-2 px-4">Learn more</a>
      </div>
    </div>
  );
}

interface SimpleProductCardProps {
  name: string;
  price: string;
  note?: string;
}

export function SimpleProductCard({ name, price, note }: SimpleProductCardProps) {
  return (
    <div className="product-card">
      <div className="bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl w-full h-28 mb-4 flex items-center justify-center">
        <span className="text-3xl opacity-50">🎧</span>
      </div>
      <h3 className="font-semibold text-base text-gray-900">{name}</h3>
      <div className="mt-2 flex items-baseline gap-2">
        <p className="font-medium text-gray-900">{price}</p>
        {note && <span className="text-xs text-gray-500">{note}</span>}
      </div>
    </div>
  );
}

interface AccessoryCardProps {
  name: string;
  price: string;
}

export function AccessoryCard({ name, price }: AccessoryCardProps) {
  return (
    <div className="product-card py-4">
      <div className="bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl w-full h-24 mb-4 flex items-center justify-center">
        <span className="text-2xl opacity-50">🔌</span>
      </div>
      <h3 className="font-medium text-sm text-gray-900 line-clamp-2">{name}</h3>
      <p className="font-medium text-gray-900 mt-2">{price}</p>
    </div>
  );
}

