interface SectionNavProps {
  sections: string[];
}

export function SectionNav({ sections }: SectionNavProps) {
  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80;
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth',
      });
    }
  };

  const getId = (section: string) => section.toLowerCase().replace(/\s+/g, '-');

  return (
    <div className="section-nav">
      <div className="max-w-6xl mx-auto px-4">
        <div className="flex items-center gap-1 overflow-x-auto py-2 scrollbar-hide">
          {sections.map((section) => (
            <button
              key={section}
              onClick={() => scrollToSection(getId(section))}
              className="text-sm font-medium text-gray-600 hover:text-gray-900 px-4 py-2 rounded-full hover:bg-gray-200 transition-colors whitespace-nowrap"
            >
              {section}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

