import { useState } from 'react';
import { Nav } from '../components/Nav';
import { Footer } from '../components/Footer';
import { siteConfig } from '../config/site';

export function HomePage() {
  const [activeTab, setActiveTab] = useState('streaming');

  return (
    <div className="min-h-screen bg-[#f5f5f7]">
      <Nav currentPage="index.html" />

      {/* Ribbon Banner */}
      <div className="bg-[#0071e3] text-white text-center py-2.5 px-4 text-sm">
        <a href="store.html" className="hover:underline">
          {siteConfig.ribbonBanner}
        </a>
      </div>

      {/* Hero Product Showcase */}
      <section className="max-w-6xl mx-auto px-4 pt-16 pb-12">
        <h1 className="text-5xl md:text-6xl font-semibold text-center text-[#1d1d1f] animate-fade-in-up">
          {siteConfig.tagline}
        </h1>
        <p className="text-xl text-[#6e6e73] text-center mt-4 animate-fade-in-up delay-100">
          The latest products. The best deals. The experts who can help.
        </p>
      </section>

      {/* Product Grid */}
      <section className="max-w-6xl mx-auto px-4 pb-16">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {siteConfig.homepageProducts.map((product, index) => (
            <div
              key={product.title}
              className={`bg-white rounded-3xl p-8 animate-fade-in-up`}
              style={{ animationDelay: `${(index + 2) * 100}ms` }}
            >
              <div className={`bg-gradient-to-br ${product.gradient} rounded-2xl w-full h-48 mb-6 flex items-center justify-center`}>
                <span className="text-6xl opacity-70">📱</span>
              </div>
              <h2 className="text-2xl font-semibold text-[#1d1d1f]">{product.title}</h2>
              <p className="text-[#6e6e73] mt-2">{product.tagline}</p>
              <div className="mt-6 flex gap-3">
                {product.ctas.map((cta) => (
                  <a
                    key={cta.label}
                    href={cta.href}
                    className={cta.label === 'Buy' ? 'btn-primary' : 'btn-secondary'}
                  >
                    {cta.label}
                  </a>
                ))}
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Entertainment Carousel with Tabs */}
      <section className="max-w-6xl mx-auto px-4 py-16">
        <CarouselWithTabs />
      </section>

      <Footer />
    </div>
  );
}

function CarouselWithTabs() {
  const [activeTab, setActiveTab] = useState('streaming');
  const tabs = siteConfig.entertainmentTabs;

  const currentContent = tabs.find(t => t.id === activeTab)?.items || [];

  return (
    <div>
      <h2 className="text-3xl font-semibold text-[#1d1d1f] mb-2">Endless entertainment.</h2>
      <p className="text-[#6e6e73] mb-6">Streaming, fitness, gaming, and music — all in one place.</p>

      {/* Tabs */}
      <div className="flex gap-1 mb-6 border-b border-gray-200">
        {tabs.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`tab-btn ${activeTab === tab.id ? 'active' : ''}`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
        {currentContent.map((item, index) => (
          <div key={index} className="bg-white rounded-2xl p-6 hover:shadow-lg transition-shadow">
            <div className="bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl w-full h-32 mb-4 flex items-center justify-center">
              <span className="text-4xl opacity-50">
                {activeTab === 'streaming' && '📺'}
                {activeTab === 'fitness' && '💪'}
                {activeTab === 'gaming' && '🎮'}
                {activeTab === 'music' && '🎵'}
              </span>
            </div>
            <h3 className="font-semibold text-lg text-[#1d1d1f]">{item.title}</h3>
            <p className="text-sm text-[#6e6e73] mt-1">{item.desc}</p>
            <a href="#" className="inline-block mt-4 text-[#0066cc] text-sm font-medium hover:underline">
              {item.cta} →
            </a>
          </div>
        ))}
      </div>
    </div>
  );
}

