import { Nav } from '../components/Nav';
import { Footer } from '../components/Footer';
import { Carousel } from '../components/Carousel';
import { ProductCard, SimpleProductCard, AccessoryCard } from '../components/ProductCard';
import { siteConfig } from '../config/site';

export function StorePage() {
  return (
    <div className="min-h-screen bg-[#f5f5f7]">
      <Nav currentPage="store.html" />

      {/* Store Hero */}
      <section className="max-w-6xl mx-auto px-4 pt-16 pb-12 text-center">
        <h1 className="text-5xl font-semibold text-[#1d1d1f]">Store</h1>
        <p className="text-xl text-[#6e6e73] mt-3">The best way to buy the products you love.</p>
        <div className="mt-6 flex flex-wrap justify-center gap-3">
          <a href="#" className="btn-primary">Connect with a Specialist</a>
          <a href="#" className="btn-secondary">Find an Orchard Store</a>
        </div>
      </section>

      {/* Product Icon Bar */}
      <section className="max-w-6xl mx-auto px-4 pb-12">
        <div className="flex gap-8 overflow-x-auto py-4 justify-between">
          {siteConfig.productCategories.map((cat) => (
            <a key={cat.label} href={cat.href || '#'} className="flex flex-col items-center gap-2 min-w-[60px]">
              <div className="w-12 h-12 bg-gray-200 rounded-xl flex items-center justify-center text-2xl">
                {cat.icon === 'laptop' && '💻'}
                {cat.icon === 'phone' && '📱'}
                {cat.icon === 'tablet' && '📲'}
                {cat.icon === 'watch' && '⌚'}
                {cat.icon === 'headphones' && '🎧'}
                {cat.icon === 'activity' && '📊'}
                {cat.icon === 'tv' && '📺'}
                {cat.icon === 'speaker' && '🔊'}
                {cat.icon === 'box' && '📦'}
                {cat.icon === 'gift' && '🎁'}
              </div>
              <span className="text-xs font-medium text-[#1d1d1f] whitespace-nowrap">{cat.label}</span>
            </a>
          ))}
        </div>
      </section>

      {/* Latest Products Carousel */}
      <section className="max-w-6xl mx-auto px-4 py-12">
        <Carousel title="The latest." subtitle="Take a look at what's new, right now.">
          {siteConfig.latestProducts.map((product) => (
            <ProductCard
              key={product.name}
              name={product.name}
              tagline={product.tagline}
              price={product.price}
              monthly={product.monthly}
              badge={product.badge}
            />
          ))}
        </Carousel>
      </section>

      {/* Help Section */}
      <section className="max-w-6xl mx-auto px-4 py-12">
        <Carousel title="Help is here." subtitle="Whenever and however you need it.">
          {siteConfig.helpSections.map((help) => (
            <div key={help.title} className="product-card flex-0-0-300">
              <div className="bg-gradient-to-br from-blue-100 to-blue-200 rounded-xl w-full h-20 mb-4 flex items-center justify-center">
                <span className="text-3xl opacity-70">🛟</span>
              </div>
              <h3 className="font-semibold text-lg text-gray-900">{help.title}</h3>
              <p className="text-sm text-gray-500 mt-2">{help.desc}</p>
            </div>
          ))}
        </Carousel>
      </section>

      {/* Store Difference */}
      <section className="max-w-6xl mx-auto px-4 py-12">
        <Carousel title="The Orchard Store difference." subtitle="Even more reasons to shop with us.">
          {siteConfig.storeDifference.map((item) => (
            <div key={item.title} className="product-card flex-0-0-300">
              <div className="bg-gradient-to-br from-emerald-100 to-emerald-200 rounded-xl w-full h-20 mb-4 flex items-center justify-center">
                <span className="text-3xl opacity-70">✨</span>
              </div>
              <h3 className="font-semibold text-lg text-gray-900">{item.title}</h3>
              <p className="text-sm text-gray-500 mt-2">{item.desc}</p>
            </div>
          ))}
        </Carousel>
      </section>

      {/* Accessories Carousel */}
      <section className="max-w-6xl mx-auto px-4 py-12 bg-white">
        <div className="max-w-6xl mx-auto">
          <Carousel title="Accessories." subtitle="Essentials that pair perfectly with your favorite devices.">
            {siteConfig.accessories.map((acc) => (
              <AccessoryCard key={acc.name} name={acc.name} price={acc.price} />
            ))}
          </Carousel>
        </div>
      </section>

      {/* Audio Carousel */}
      <section className="max-w-6xl mx-auto px-4 py-12">
        <Carousel title="Loud and clear." subtitle="Unparalleled choices for rich, high-quality sound.">
          {siteConfig.audioProducts.map((audio) => (
            <SimpleProductCard
              key={audio.name}
              name={audio.name}
              price={audio.price}
              note={audio.note}
            />
          ))}
        </Carousel>
        <p className="mt-4 text-sm text-[#6e6e73]">
          Get 3 months of Orchard Music free — included with the purchase of select devices.
        </p>
      </section>

      {/* Brand Collaboration */}
      <section className="max-w-6xl mx-auto px-4 py-12">
        <div className="bg-gradient-to-br from-orange-100 to-rose-100 rounded-3xl p-10 text-center">
          <h2 className="text-3xl font-semibold text-[#1d1d1f]">{siteConfig.brandCollab.title}</h2>
          <p className="text-xl text-[#6e6e73] mt-2">{siteConfig.brandCollab.subtitle}</p>
          <p className="text-[#6e6e73] mt-4 max-w-xl mx-auto">{siteConfig.brandCollab.desc}</p>
          <div className="mt-6 flex justify-center gap-3">
            <a href="#" className="btn-primary">Learn more</a>
            <a href="#" className="btn-secondary">Shop now</a>
          </div>
        </div>
      </section>

      {/* Savings Offers */}
      <section className="max-w-6xl mx-auto px-4 py-12">
        <Carousel title="Savings and offers." subtitle="Exclusive deals, special stores and more.">
          {siteConfig.savingsOffers.map((offer) => (
            <div key={offer.title} className="product-card flex-0-0-300">
              <div className="bg-gradient-to-br from-purple-100 to-purple-200 rounded-xl w-full h-20 mb-4 flex items-center justify-center">
                <span className="text-3xl opacity-70">🏷️</span>
              </div>
              <h3 className="font-semibold text-lg text-gray-900">{offer.title}</h3>
              <p className="text-sm text-gray-500 mt-2">{offer.desc}</p>
            </div>
          ))}
        </Carousel>
      </section>

      {/* Quick Links */}
      <section className="max-w-6xl mx-auto px-4 py-12">
        <div className="flex flex-wrap gap-4 justify-center">
          {siteConfig.quickLinks.map((link) => (
            <a
              key={link.label}
              href={link.href}
              className="px-6 py-3 bg-white rounded-full text-sm font-medium text-[#0066cc] hover:bg-blue-50 transition-colors"
            >
              {link.label}
            </a>
          ))}
        </div>
      </section>

      <Footer />
    </div>
  );
}

