  <script>
    // Section Navigation - scroll to section
    document.querySelectorAll('.section-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.dataset.target;
        const element = document.getElementById(target);
        if (element) {
          const offset = 100;
          const top = element.getBoundingClientRect().top + window.pageYOffset - offset;
          window.scrollTo({ top, behavior: 'smooth' });
        }
      });
    });

    // Carousel functionality
    document.querySelectorAll('.carousel-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const direction = btn.classList.contains('prev') ? -1 : 1;
        const carouselType = btn.dataset.carousel;
        const track = document.getElementById(`${carouselType}-track`);
        if (!track) return;

        const scrollAmount = 280 * direction;
        track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
      });
    });

    // Update carousel button states
    function updateCarouselButtons() {
      document.querySelectorAll('.carousel-track').forEach(track => {
        const prevBtn = track.parentElement.querySelector('.carousel-btn.prev');
        const nextBtn = track.parentElement.querySelector('.carousel-btn.next');
        if (!prevBtn || !nextBtn) return;

        const scrollLeft = track.scrollLeft;
        const maxScroll = track.scrollWidth - track.clientWidth;

        prevBtn.classList.toggle('disabled', scrollLeft <= 0);
        nextBtn.classList.toggle('disabled', scrollLeft >= maxScroll - 10);
      });
    }

    document.querySelectorAll('.carousel-track').forEach(track => {
      track.addEventListener('scroll', updateCarouselButtons);
      updateCarouselButtons();
    });

    // Footer accordion on mobile
    if (window.innerWidth <= 768) {
      document.querySelectorAll('.footer-section .toggle').forEach(toggle => {
        toggle.addEventListener('click', () => {
          const section = toggle.parentElement;
          section.classList.toggle('open');
        });
      });
    }
  </script>
